using System;using System.Xml.Linq;class LoginTest{static void Main(){if(Reader.SingleUser(XDocument.Parse("<SessionInfo><Users><User>fritz1234</User></Users></SessionInfo>"))!="fritz1234")throw new Exception();foreach(var s in new[]{"<Users/>","<Users><User>A</User><User>B</User></Users>"}){try{Reader.SingleUser(XDocument.Parse(s));}catch(InvalidOperationException){continue;}throw new Exception();}Console.WriteLine("OK");}}